 		t.Run(tt.name, func(t *testing.T) {
 			d := NewDynamicEnqueueRequest()
 			if err := d.AddHandler(tt.args); (err != nil) != tt.wantErr {
 				t.Errorf("DynamicEnqueueRequest.AddHandler() error = %v, wantErr %v", err, tt.wantErr)
 			}
