 		return []reconcile.Request{
 			{NamespacedName: types.NamespacedName{
 				Namespace: labels[RemoteClusterNamespaceLabelName],
 				Name:      labels[RemoteClusterNameLabelName]},
 			},
 		}
 	}
 }

