 	require.NoError(t, webhook.InjectLogger(log))

 	server := httptest.NewServer(webhook)
 	defer server.Close()

 	client := server.Client()

 	for _, tt := range tests {
 		tc := tt
 		t.Run(tc.Name, func(t *testing.T) {
 			uid := tc.Name
